<script setup lang="ts">
import {ref,onMounted} from 'vue';import {hoursToSeconds,minutesToSeconds} from '../lib/interval';import {api,errorText} from '../lib/api';import type {Configuration,Service} from '../types';import Icon from '../components/Icon.vue';import Notice from '../components/Notice.vue';import Modal from '../components/Modal.vue'
const intervalHours=ref<number|string>(6)
const sourceIntervalMinutes=ref<number|string>(360)
const config=ref<Configuration>(),form=ref<Service>(),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),confirmOpen=ref(false),confirmText=ref('')
async function load(){loading.value=true;error.value='';try{config.value=await api<Configuration>('/api/admin/config');form.value={...config.value.service};intervalHours.value=config.value.service.interval_seconds/3600;sourceIntervalMinutes.value=(config.value.service.source_interval_seconds??config.value.service.interval_seconds)/60}catch(e){error.value=errorText(e)}finally{loading.value=false}}
onMounted(load)
function validInterval(){try{hoursToSeconds(intervalHours.value);minutesToSeconds(sourceIntervalMinutes.value);return true}catch(e){error.value=errorText(e);success.value='';return false}}
function needsConfirmation(){return !!config.value&&!!form.value&&!form.value.dry_run&&(config.value.service.dry_run||form.value.source_url!==config.value.service.source_url)}
function submit(){if(!form.value||!validInterval())return;if(needsConfirmation()){confirmText.value='';confirmOpen.value=true}else void save()}
async function save(){if(!config.value||!form.value||!validInterval())return;busy.value=true;error.value='';success.value='';try{const values={source_url:form.value.source_url,interval_seconds:hoursToSeconds(intervalHours.value),source_interval_seconds:minutesToSeconds(sourceIntervalMinutes.value),timeout_seconds:form.value.timeout_seconds,attempts:form.value.attempts,dry_run:form.value.dry_run,max_ips:form.value.max_ips};const service=Object.fromEntries(Object.entries(values).filter(([key,value])=>value!==config.value!.service[key as keyof Service]));if(needsConfirmation())service.dry_run=false;config.value=await api<Configuration>('/api/admin/config',{method:'PATCH',body:{revision:config.value.revision,service,...(needsConfirmation()?{confirm_apply:true}:{})}});form.value={...config.value.service};intervalHours.value=config.value.service.interval_seconds/3600;sourceIntervalMinutes.value=(config.value.service.source_interval_seconds??config.value.service.interval_seconds)/60;confirmOpen.value=false;success.value='设置已保存并生效。'}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script><template><div class="admin-heading"><div><span class="eyebrow">SERVICE SETTINGS</span><h1>服务设置</h1><p>配置优选来源与任务调度。</p></div><button class="btn" :disabled="loading||busy" @click="load"><Icon name="refresh" :size="17"/>重新加载</button></div><Notice :message="error"/><Notice :message="success" kind="success"/><form v-if="form" @submit.prevent="submit"><section class="card settings-section"><div class="card-heading"><h2>IP 获取</h2><p class="muted">只刷新 IP，不修改 DNS，也不执行测速。</p></div><label class="field">IP 获取间隔（min）<input v-model="sourceIntervalMinutes" type="number" min="0.5" max="10080" step="any" required><span class="help">支持小数，须对应整数秒；0.5 至 10080 min。</span></label><label class="field">优选来源<select v-model="form.source_url" @change="form.dry_run=true"><option value="https://ip.164746.xyz/ipTop.html">ip.164746.xyz · 原有来源</option><option value="https://ip.v2too.top/api/nodes">ip.v2too.top · 三网首选 IP</option><option v-if="config && !['https://ip.164746.xyz/ipTop.html','https://ip.v2too.top/api/nodes'].includes(config.service.source_url)" :value="config.service.source_url">服务器配置来源</option></select></label><div class="form-grid"><label class="field">最大 IP 数量<input v-model.number="form.max_ips" type="number" min="1" max="1000" required><span class="help">超限、空内容和非法 IP 会被拒绝。</span></label><label class="field">请求超时（秒）<input v-model.number="form.timeout_seconds" type="number" min="1" max="60" required></label></div></section><section class="card settings-section"><div class="card-heading"><h2>DNS 同步</h2><p class="muted">使用本次启动后最近成功获取的 IP；来源失败或切换后暂停写入，直到重新获取成功。</p></div><div class="form-grid"><label class="field">DNS 同步间隔（h）<input v-model="intervalHours" type="number" :min="30/3600" :max="604800/3600" step="any" required><span class="help">独立于 IP 获取；30 秒至 168 h，支持小数。</span></label><label class="field">读取重试次数<input v-model.number="form.attempts" type="number" min="1" max="5" required><span class="help">写请求不会自动重发。</span></label></div><label class="field">运行模式<select v-model="form.dry_run"><option :value="true">预览模式 · 不修改 DNS</option><option :value="false">正式同步 · 按周期更新 DNS</option></select></label><div :class="['notice',form.dry_run?'info':'warning']"><Icon :name="form.dry_run?'lock':'shield'" :size="18"/>{{form.dry_run?'只获取地址、读取现有解析和生成更新计划。':'正式模式会修改已有 A 记录；启用前请核对目标。'}}</div></section><div class="button-row wrap settings-save"><button class="btn primary" :disabled="busy"><Icon name="check" :size="18"/>{{busy?'保存中…':'保存设置'}}</button><span class="help">并发修改会被拒绝，请重新加载后再提交。</span></div></form><div v-else class="card loading-state">{{loading?'正在加载配置…':'配置暂不可用，请重试。'}}</div><Modal :open="confirmOpen" title="启用正式同步" :busy="busy" @close="confirmOpen=false"><p>保存后，后台计划任务可能立即开始更新 {{config?.targets.length||0}} 个 DNS 目标。多条修改不是事务，不会自动回滚。</p><div class="notice warning">请先完成一次预览。</div><label class="field">输入“启用同步”确认<input v-model="confirmText" autocomplete="off" placeholder="启用同步"></label><Notice :message="error"/><div class="modal-actions"><button class="btn" :disabled="busy" @click="confirmOpen=false">取消</button><button class="btn primary" :disabled="busy||confirmText!=='启用同步'" @click="save">确认启用</button></div></Modal></template>
